query:
NODE VALUE out_degree SumAgg<INT64> = 0
TABLE degrees {id STRING, degree INT64}

MATCH (p:player)-[e:follow]->(q:player)
PER PATH {
  SET p.@out_degree += 1
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@out_degree AS degree INTO degrees
}

FOR r IN degrees
RETURN r.id AS id, r.degree AS degree
